def pct_rank(arr):
    """Percentile rank transform - guarantees Uniform(0,1) marginal."""
    import pandas as pd
    import numpy as np
    s = pd.Series(arr)
    if len(s) <= 1 or np.all(s == s.iloc[0]):
        return np.full_like(s, 0.5, dtype=np.float32)
    return s.rank(method='average', pct=True).values

