# ============================================================
# OOF-CALIBRATED STACKING (Optimized per-pathology weights)
# ============================================================

def blend_predictions(raptor_preds, e12_preds, e13_preds):
    """
    Blend three model predictions using per-pathology optimized percentile-rank weights.
    
    Args:
        raptor_preds: (N, 12) array
        e12_preds: (N, 12) array  
        e13_preds: (N, 12) array
    
    Returns:
        blended: (N, 12) array in [0.0001, 0.9999]
    """
    import numpy as np
    import pandas as pd
    
    N = raptor_preds.shape[0]
    blended = np.zeros((N, 12), dtype=np.float32)
    
    for j, lbl in enumerate(TARGETS):
        w = OOF_WEIGHTS.get(lbl, {'w_raptor': 0.70, 'w_e12': 0.15, 'w_e13': 0.15})
        
        r_raptor = pct_rank(raptor_preds[:, j])
        r_e12 = pct_rank(e12_preds[:, j])
        r_e13 = pct_rank(e13_preds[:, j])
        
        blended[:, j] = w['w_raptor'] * r_raptor + w['w_e12'] * r_e12 + w['w_e13'] * r_e13
    
    # Clamp for numerical stability
    blended = np.clip(blended, 0.0001, 0.9999)
    return blended

